with valid as (select *, weekofyear(last_restock) as last_restock_weekofyear from inventory where last_restock < '2025-06-01') select case when last_restock_weekofyear >= 62 then 'PREMIUM' else 'STANDARD' end as last_restock_weekofyear_tier, store_id, case when quantity >= 194 then 'HIGH' else 'LOW' end as quantity_tier, approx_percentile(quantity, 0.5) as quantity_p50, approx_percentile(quantity, array(0.25, 0.5, 0.75)) as quantity_quartiles, grouping_id() as grouping_id from valid group by grouping sets ((case when last_restock_weekofyear >= 62 then 'PREMIUM' else 'STANDARD' end, store_id, case when quantity >= 194 then 'HIGH' else 'LOW' end), (case when last_restock_weekofyear >= 62 then 'PREMIUM' else 'STANDARD' end, store_id)) having approx_percentile(quantity, 0.5) >= 0 order by quantity_p50 desc nulls last;
